// IMAGE — overlays moving dots; centered/zoomed; smooth saturated colors
// Reads trails from iChannel0 (Buffer A)

#define SPEED         10.0
#define RESTART_SEC    8.0
#define ZOOM           4.0
#define D              1
#define SEED         123.0
#define DOT_RAW_PX     3.0
#define DOT_CES_PX     3.6
#define ANGLE_EPS    0.002
#define AUTO_SCALE       1
#define COLOR_RATE     0.18

// palette tuning (match Buffer A)
#define SAT_BOOST      0.75
#define VAL_SCALE      0.52
#define GAMMA          1.08

float h1(float x){ return fract(sin(x)*43758.5453123); }

void toWorld(vec2 fragCoord, out vec2 p, out float px){
    vec2 R=iResolution.xy; float s=min(R.x,R.y), W=2.2;
    vec2 c0=0.5*R; p=((fragCoord-c0)/s)*(2.0*W); px=(2.0*W)/s;
}

vec2 cmul(vec2 a, vec2 b){ return vec2(a.x*b.x - a.y*b.y, a.x*b.y + a.y*b.x); }
vec2 csub(vec2 a, vec2 b){ return a - b; }
vec2 cdiv(vec2 a, vec2 b){
    float d=dot(b,b);
    return vec2((a.x*b.x + a.y*b.y)/d, (a.y*b.x - a.x*b.y)/d);
}
vec2 zpow_polar(float r, float th, float k){ float rk=pow(r,k), a=k*th; return rk*vec2(cos(a),sin(a)); }

vec2 sampleZ(int j, float epochShift, out float r, out float th){
    float s=SEED + epochShift + float(j)*19.19; float u=h1(s+5.91);
    th=6.28318530718*u; if(abs(sin(0.5*th))<ANGLE_EPS) th += 2.0*ANGLE_EPS;
    r=1.0; return vec2(cos(th), sin(th));
}
vec2 cesaroLimit(vec2 z){ return cdiv(z, csub(vec2(1.0,0.0), z)); }

void centerAndScale(float epochShift, out vec2 C, out float S){
    C=vec2(0.0); float maxR=1.0;
    for(int j=0;j<D;++j){
        float r, th; vec2 z=sampleZ(j, epochShift, r, th);
        C += cesaroLimit(z);
        float R = 1.0 / max(length(csub(vec2(1.0,0.0), z)), 1e-4);
        maxR = max(maxR, R);
    }
    C /= float(D);
#if AUTO_SCALE
    S = (1.15*maxR)/ZOOM;
#else
    S = 1.0/ZOOM;
#endif
}

// start k=1; S1 = σ1 = z
void pos_at(vec2 z, float r, float th, float k, out vec2 S, out vec2 Sig){
    if(k <= 1.0000001){ S=z; Sig=z; return; }
    vec2 ONE=vec2(1.0,0.0), zk=zpow_polar(r,th,k), den=csub(ONE,z);
    vec2 inv1=cdiv(ONE,den), inv2=cmul(inv1,inv1);
    S   = cdiv( cmul(z, csub(ONE, zk)), den );
    vec2 part = cdiv( cmul(cmul(z,z), csub(ONE, zk)), vec2(k,0.0) );
    Sig = csub( cdiv(z, den), cmul(part, inv2) );
}

// smooth palette (same as Buffer A)
vec3 pal_base(float t){
    const float TAU=6.28318530718;
    vec3 a=vec3(0.56,0.53,0.54), b=vec3(0.44), c=vec3(1.0), d=vec3(0.00,0.33,0.67);
    return a + b*cos(TAU*(c*t + d));
}
vec3 pal_tuned(vec3 col){
    float l=dot(col, vec3(0.299,0.587,0.114));
    col = mix(vec3(l), col, SAT_BOOST);
    col = pow(max(col,0.0), vec3(GAMMA));
    col *= VAL_SCALE;
    return clamp(col,0.0,1.0);
}
vec3 pal(float t){ return pal_tuned(pal_base(t)); }
vec3 colRaw(float t){ return pal(t); }
vec3 colCes(float t){ return pal(t + 0.5); }

// ----------------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 p; float px; toWorld(fragCoord, p, px);
    vec3 col = texture(iChannel0, fragCoord/iResolution.xy).rgb;

    float epoch      = floor(iTime / RESTART_SEC);
    float epochShift = epoch*9973.0;

    vec2 C; float S; centerAndScale(epochShift, C, S);

    float t = mod(iTime, RESTART_SEC)*SPEED + 1.0;
    float n = floor(t), ph = fract(t);

    float r, th; vec2 z = sampleZ(0, epochShift, r, th);
    vec2 S0,Sig0,S1,Sig1; pos_at(z,r,th,n, S0,Sig0); pos_at(z,r,th,n+1.0, S1,Sig1);

    vec2 rawDot = (mix(S0,S1,ph)   - C)/S;
    vec2 cesDot = (mix(Sig0,Sig1,ph)- C)/S;

    float phase = iTime*COLOR_RATE + h1(epoch*0.137 + 0.314);
    vec3  inkR  = colRaw(phase);
    vec3  inkC  = colCes(phase);

    float aR = smoothstep(DOT_RAW_PX*px, 0.0, length(p - rawDot));
    float aC = smoothstep(DOT_CES_PX*px, 0.0, length(p - cesDot));
    col = mix(col, inkR, aR);
    col = mix(col, inkC, aC);

    fragColor = vec4(col, 1.0);
}

// BUFFER A — pen-style trails with smooth saturated colors (opposite hues)
// iChannel0 must point to Buffer A (self-feedback)

#define SPEED         10.0   // steps per second
#define RESTART_SEC    8.0   // reseed + recenter every N seconds
#define LINE_PX        2.0   // trail thickness in screen px
#define ZOOM           4.0   // zoom in
#define D              1     // number of seeds (you’re using 1)
#define SEED         123.0   // base RNG seed
#define FADE          0.95   // trail persistence
#define ANGLE_EPS     0.002  // avoid exactly z=1
#define AUTO_SCALE       1   // fit to frame then apply ZOOM

// color timing (independent of SPEED)
#define COLOR_RATE     0.18  // try 0.12–0.30 for slower/faster hue drift

// ---- palette tuning (richer, a bit darker) ----
#define SAT_BOOST      0.45  // >1 increases saturation
#define VAL_SCALE      0.72  // <1 lowers brightness slightly
#define GAMMA          0.48  // >1 deepens midtones

// ----------------------------- helpers --------------------------------
float h1(float x){ return fract(sin(x)*43758.5453123); }

void toWorld(vec2 fragCoord, out vec2 p, out float px){
    vec2 R = iResolution.xy; float s = min(R.x,R.y), W = 2.2;
    vec2 c0 = 0.5*R; p = ((fragCoord - c0)/s)*(2.0*W); px = (2.0*W)/s;
}

float sdSegment(vec2 p, vec2 a, vec2 b){
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa,ba)/max(dot(ba,ba),1e-9), 0., 1.);
    return length(pa - ba*h);
}

vec2 cmul(vec2 a, vec2 b){ return vec2(a.x*b.x - a.y*b.y, a.x*b.y + a.y*b.x); }
vec2 csub(vec2 a, vec2 b){ return a - b; }
vec2 cdiv(vec2 a, vec2 b){
    float d = dot(b,b);
    return vec2((a.x*b.x + a.y*b.y)/d, (a.y*b.x - a.x*b.y)/d);
}

vec2 zpow_polar(float r, float th, float k){
    float rk = pow(r, k), a = k*th;
    return rk * vec2(cos(a), sin(a));
}

// epoch-aware unit-circle seed (avoid z=1)
vec2 sampleZ(int j, float epochShift, out float r, out float th){
    float s = SEED + epochShift + float(j)*19.19;
    float u = h1(s+5.91);
    th = 6.28318530718 * u;
    if (abs(sin(0.5*th)) < ANGLE_EPS) th += 2.0*ANGLE_EPS;
    r = 1.0;
    return vec2(cos(th), sin(th));
}

// Cesàro limit (k=1 start): L = z/(1 - z)
vec2 cesaroLimit(vec2 z){ return cdiv(z, csub(vec2(1.0,0.0), z)); }

// center at Cesàro limit(s); scale to fit, then ZOOM
void centerAndScale(float epochShift, out vec2 C, out float S){
    C = vec2(0.0); float maxR = 1.0;
    for(int j=0;j<D;++j){
        float r, th; vec2 z = sampleZ(j, epochShift, r, th);
        C += cesaroLimit(z);
        float R = 1.0 / max(length(csub(vec2(1.0,0.0), z)), 1e-4); // |1/(1-z)|
        maxR = max(maxR, R);
    }
    C /= float(D);
#if AUTO_SCALE
    S = (1.15*maxR) / ZOOM;
#else
    S = 1.0 / ZOOM;
#endif
}

// start k=1; exact S1 = σ1 = z
//   S_k  = z(1 - z^k)/(1 - z)
//   σ_k  = z/(1 - z) - [z^2 (1 - z^k)] / [k (1 - z)^2]
void pos_at(vec2 z, float r, float th, float k, out vec2 S, out vec2 Sig){
    if(k <= 1.0000001){ S = z; Sig = z; return; }
    vec2 ONE = vec2(1.0,0.0);
    vec2 zk  = zpow_polar(r, th, k);
    vec2 den = csub(ONE, z);
    vec2 inv1= cdiv(ONE, den);
    vec2 inv2= cmul(inv1, inv1);
    S   = cdiv( cmul(z, csub(ONE, zk)), den );
    vec2 part = cdiv( cmul(cmul(z,z), csub(ONE, zk)), vec2(k,0.0) );
    Sig = csub( cdiv(z, den), cmul(part, inv2) );
}

// ---- smooth cosine palette (IQ-style) + tuning ------------------------
vec3 pal_base(float t){
    const float TAU = 6.28318530718;
    vec3 a = vec3(0.56, 0.53, 0.54);   // base
    vec3 b = vec3(0.44, 0.44, 0.44);   // amplitude
    vec3 c = vec3(1.0);                // frequency
    vec3 d = vec3(0.00, 0.33, 0.67);   // per-channel phase
    return a + b * cos(TAU*(c*t + d));
}
vec3 pal_tuned(vec3 col){
    float l = dot(col, vec3(0.299,0.587,0.114));
    col = mix(vec3(l), col, SAT_BOOST);
    col = pow(max(col, 0.0), vec3(GAMMA));
    col *= VAL_SCALE;
    return clamp(col, 0.0, 1.0);
}
vec3 pal(float t){ return pal_tuned(pal_base(t)); }
vec3 colRaw(float t){ return pal(t); }         // ordinary
vec3 colCes(float t){ return pal(t + 0.5); }   // Cesàro (opposite hue)

// ----------------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord){
    float epoch     = floor(iTime / RESTART_SEC);
    float epochTag  = fract(sin((epoch+1.0)*12.9898)*43758.5453); // store in alpha
    float epochSeed = h1(epoch*0.137 + 0.314);                    // color phase jitter

    vec4 prev   = (iFrame==0 ? vec4(1.0) : texture(iChannel0, fragCoord/iResolution.xy));
    bool fresh  = (iFrame==0) || (abs(prev.a - epochTag) > 1e-4); // clear on restart
    vec3 canvas = fresh ? vec3(1.0) : prev.rgb;
    vec3 col    = mix(vec3(1.0), canvas, FADE);

    vec2 p; float px; toWorld(fragCoord, p, px);
    float lw = LINE_PX * px;

    vec2 C; float S; centerAndScale(epoch*9973.0, C, S);

    // motion time (within epoch)
    float tL = mod(iTime, RESTART_SEC);
    float t  = tL*SPEED + 1.0;
    float dt = max(iTimeDelta*SPEED, 1e-4);
    float n0 = floor(max(1.0, t - dt)), ph0 = fract(max(1.0, t - dt));
    float n1 = floor(t),                ph1 = fract(t);

    // color phase: continuous in real time, independent of SPEED
    float phase = iTime*COLOR_RATE + epochSeed;

    for(int j=0; j<D; ++j){
        float r, th; vec2 z = sampleZ(j, epoch*9973.0, r, th);

        // Ordinary (RAW) segment
        vec2 S00,Sx,S01,Sx2;  pos_at(z,r,th,n0,    S00,Sx);
                              pos_at(z,r,th,n0+1., S01,Sx2);
        vec2 P0 = (mix(S00,S01,ph0) - C)/S;

        vec2 S10,Sx3,S11,Sx4; pos_at(z,r,th,n1,    S10,Sx3);
                              pos_at(z,r,th,n1+1., S11,Sx4);
        vec2 P1 = (mix(S10,S11,ph1) - C)/S;

        float a = smoothstep(lw*1.3, lw*0.6, sdSegment(p, P0, P1));
        col = mix(col, colRaw(phase), a);

        // Cesàro segment
        vec2 T0, Sig0, T1, Sig1;
        pos_at(z,r,th,n0,    T0, Sig0);
        pos_at(z,r,th,n0+1., T1, Sig1);
        vec2 Q0 = (mix(Sig0,Sig1,ph0) - C)/S;

        vec2 U0, Sig2, U1, Sig3;
        pos_at(z,r,th,n1,    U0, Sig2);
        pos_at(z,r,th,n1+1., U1, Sig3);
        vec2 Q1 = (mix(Sig2,Sig3,ph1) - C)/S;

        float b = smoothstep(lw*1.3, lw*0.6, sdSegment(p, Q0, Q1));
        col = mix(col, colCes(phase), b);
    }

    fragColor = vec4(col, epochTag);
}
